<body>
<canvas id="game"></canvas>
<div id="scan" class="layer"></div>

<div class="hud top layer">
  <div class="brand">
    <div class="glyph">
      <svg viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="2.4"
           stroke-linejoin="round" stroke-linecap="round">
        <path d="M6 20 L26 12 L34 20 L26 28 L18 20 Z"/>
        <circle cx="25" cy="20" r="1.8" fill="currentColor" stroke="none"/>
